"""Small resilient HTTP client for the order service (working script, not a deliverable)."""
import json
import re
import sys
import time
import urllib.error
import urllib.request
from email.utils import parsedate_to_datetime
from datetime import datetime, timezone

BASE = "http://localhost:8080"
LOG = "/tmp/recon/events.log"


def log(msg):
    line = f"{datetime.now(timezone.utc).strftime('%H:%M:%S.%f')[:-3]} {msg}"
    with open(LOG, "a") as fh:
        fh.write(line + "\n")
    print(line, file=sys.stderr, flush=True)


class Unexpected(Exception):
    pass


class Client:
    def __init__(self):
        self.token = None
        self.tokens_issued = 0
        self.request_count = 0
        self.status_counts = {}

    # -- low level ---------------------------------------------------------
    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        self.request_count += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                body = resp.read()
                status, headers = resp.status, dict(resp.headers.items())
        except urllib.error.HTTPError as err:
            body = err.read()
            status, headers = err.code, dict(err.headers.items())
        except (urllib.error.URLError, TimeoutError, ConnectionError) as err:
            return None, {}, f"{type(err).__name__}: {err}".encode()
        self.status_counts[status] = self.status_counts.get(status, 0) + 1
        return status, headers, body

    def new_token(self):
        for attempt in range(1, 11):
            status, headers, body = self._raw("POST", "/token", auth=False)
            if status == 200:
                self.token = json.loads(body)["token"]
                self.tokens_issued += 1
                log(f"token issued: {self.token} (#{self.tokens_issued})")
                return
            if status == 429:
                self._wait_for_rate_limit(status, headers, body, "POST /token")
                continue
            log(f"POST /token -> {status} {body[:200]!r}; retry {attempt}")
            time.sleep(min(2 ** attempt * 0.25, 5))
        raise Unexpected("could not obtain a token")

    @staticmethod
    def _retry_after(headers, body):
        h = {k.lower(): v for k, v in headers.items()}
        if "retry-after" in h:
            val = h["retry-after"].strip()
            try:
                return float(val)
            except ValueError:
                dt = parsedate_to_datetime(val)
                return max(0.0, (dt - datetime.now(timezone.utc)).total_seconds())
        try:
            data = json.loads(body)
        except Exception:
            data = None
        if isinstance(data, dict):
            for key in ("retry_after", "retry_after_seconds", "retry_after_s", "wait", "wait_seconds", "retry_in"):
                if key in data:
                    return float(data[key])
        return None

    def _wait_for_rate_limit(self, status, headers, body, what):
        wait = self._retry_after(headers, body)
        log(f"{what} -> {status} rate limited; headers={headers} body={body[:300]!r}; wait={wait}")
        if wait is None:
            raise Unexpected(f"rate limited but no wait hint found for {what}: {headers} {body[:300]!r}")
        time.sleep(wait + 0.25)

    # -- high level --------------------------------------------------------
    def get(self, path, max_attempts=40, allow_404=False):
        """GET an authenticated JSON resource, repeating on transient failures."""
        if self.token is None:
            self.new_token()
        for attempt in range(1, max_attempts + 1):
            status, headers, body = self._raw("GET", path, auth=True)
            if status == 200:
                try:
                    return json.loads(body)
                except ValueError:
                    log(f"GET {path} -> 200 but body is not JSON: {body[:300]!r}; retry {attempt}")
                    time.sleep(0.5)
                    continue
            if status == 404 and allow_404:
                log(f"GET {path} -> 404 body={body[:200]!r}")
                return None
            if status == 429:
                self._wait_for_rate_limit(status, headers, body, f"GET {path}")
                continue
            if status in (401, 403):
                log(f"GET {path} -> {status} headers={headers} body={body[:300]!r}; refreshing token")
                self.new_token()
                continue
            if status is None or status >= 500:
                log(f"GET {path} -> {status} body={body[:300]!r}; retry {attempt}")
                time.sleep(min(2 ** attempt * 0.25, 5))
                continue
            raise Unexpected(f"GET {path} -> {status} headers={headers} body={body[:500]!r}")
        raise Unexpected(f"GET {path}: gave up after {max_attempts} attempts")

